{
  "context": "Un cliente envía una solicitud a un servicio que publicará un comando en una cola para que otro servicio lo procese más tarde.",
  "statement": "¿Qué código de estado HTTP es el más adecuado para responder inmediatamente a esa solicitud?",
  "options": [
    {
      "id": "A",
      "text": "200 OK, porque la operación ya fue completada por el servicio consumidor."
    },
    {
      "id": "B",
      "text": "202 Accepted, porque la solicitud fue aceptada pero su procesamiento aún no termina."
    },
    {
      "id": "C",
      "text": "201 Created, porque siempre se crea un recurso nuevo en el servidor."
    },
    {
      "id": "D",
      "text": "204 No Content, porque el cliente no necesita ninguna información adicional."
    }
  ],
  "correctOptionId": "B",
  "justification": "202 indica que la petición fue aceptada para procesamiento, sin garantizar que haya terminado.",
  "bibliography": "RFC 9110 - HTTP Semantics, sección 15.3.3.",
  "competence": "Desarrollo de software",
  "topic": "Servicios web REST",
  "subtopic": "Códigos de estado",
  "difficulty": "BAJO"
}

